/* Шаблоны для строк с числом внутри, где у узбекского свой порядок слов.
   Регулярное выражение на всю строку и замена с $1, $2… (см. template в i18n.js). */
globalThis.RetroTemplatesUz = [
  [/^Ручной ввод выплат с (.+)\. В столбце указана дата выплаты за предыдущую смену\. Прежние общие выплаты без сотрудника сохранены в «Финансах дня»\.$/, "$1 sanasidan to‘lovlar qo‘lda kiritiladi. Ustunda oldingi smena uchun to‘lov sanasi ko‘rsatilgan. Xodimi ko‘rsatilmagan avvalgi umumiy to‘lovlar «Kun moliyasi»da saqlangan."],
  [/^Ручная ведомость · (.+)$/, "Qo‘lda to‘ldiriladigan qaydnoma · $1"],
  [/^Выдано (\d\d\.\d\d)$/, "$1 kuni berilgan"],
  [/^За смену (\d\d\.\d\d)$/, "$1 smenasi uchun"],
  [/^за (\d\d\.\d\d)$/, "$1 uchun"],
  [/^(.+) · выплата (\d\d\.\d\d) за смену (\d\d\.\d\d) · (выдано (.+) сум|не выдано)( · .+)?$/, "$1 · $2 to‘lovi, $3 smenasi uchun"],
  [/^(.+) · выплата (\d\d\.\d\d)(, сум)?$/, "$1 · $2 to‘lovi$3"],
  [/^В «Финансах дня» есть общая зарплата без сотрудников: (.+)\. Если вводите эти дни по людям, удалите общую строку, иначе выплата посчитается дважды\.$/, "«Kun moliyasi»da xodimsiz umumiy ish haqi bor: $1. Bu kunlarni xodimlar bo‘yicha kiritsangiz, umumiy qatorni o‘chiring, aks holda to‘lov ikki marta hisoblanadi."],
  [/^Сумма в (.+) раз больше ставки\. Нажмите Enter ещё раз, чтобы записать\.$/, "Summa stavkadan $1 baravar ko‘p. Yozish uchun Enter’ni yana bosing."],
  [/^Сумма в (.+) раз больше ставки\. Не записано — проверьте и введите ещё раз\.$/, "Summa stavkadan $1 baravar ko‘p. Yozilmadi — tekshiring va qayta kiriting."],
  [/^(\d+) (?:покупка требует|покупки требуют|покупок требуют) проверки$/, "$1 ta xarid tekshiruvni talab qiladi"],
  [/^Сегодня (\S+): продвигайте «(.+)» — маржа (\d+)%, на нём Retro зарабатывает больше всего\.$/, "Bugun $1: «$2»ni targ'ib qiling — marja $3%, Retro undan eng ko'p ishlaydi."],
  [/^«(.+)» хорошо продаётся, но маржа (\d+)% — не ставьте его в акции\.$/, "«$1» yaxshi sotilmoqda, lekin marjasi $2% — uni aksiyaga qo'ymang."],
  [/^«(.+)» почти не заказывают: (\d+) шт за неделю\. Подумайте, убрать ли из меню\.$/, "«$1» deyarli buyurtma qilinmaydi: haftada $2 dona. Menyudan olib tashlashni o'ylab ko'ring."],
  [/^Обновлено в (\d\d:\d\d) · Ташкент$/, "Yangilandi: $1 · Toshkent"],
  [/^Без привязки к начислениям: (.+?) сум\. Эти расходы не погашают долг сотрудника\.$/, "Hisoblamaga bog'lanmagan: $1 so'm. Bu xarajatlar xodim qarzini yopmaydi."],
  [/^Начисления за смену ещё не подтверждены: (\d+) сотрудник\S* без расчёта\.$/, "Smena hisoblamalari hali tasdiqlanmagan: $1 xodim hisobsiz."],
  [/^Получено от кассира за (.+?): (.+?) сум\. Учёт начат с (.+)$/, "Kassirdan olingan ($1): $2 so'm. Hisob $3 dan boshlangan"],
  [/^(\d+) в реестре · (\d+) без ставки$/, "reyestrda $1 · stavkasiz $2"],
  [/^Без ставки (\d+) · без привязки (\d+)$/, "Stavkasiz $1 · bog'lanmagan $2"],
  [/^Вход после (\d\d:\d\d)$/, "$1 dan keyin kirgan"],
  [/^Начисление (.+) сум$/, "Hisoblama $1 so'm"],
  [/^(\d+) сотрудник\S* со сменами$/, "smenali $1 xodim"],
  [/^Ведомость за (.+)$/, "$1 vedomosti"],
  [/^Зарплаты · (.+)$/, "Ish haqi · $1"],
  [/^фонд по реестру (.+) сум$/, "reyestr bo'yicha fond $1 so'm"],
  [/^Без Hikvision · (\d+)$/, "Hikvision'siz · $1"],
  [/^([\d.,]+)% выборки$/, "tanlanmaning $1%"],
  [/^✓ Распределение продаж сверено · (.+) сум$/, "✓ Savdo taqsimoti solishtirildi · $1 so'm"],
  [/^Продажи до исключений меню\. Меню: (.+?) сум(?:; исключены группы: (.+?))?\. Вне банкетной выборки: (.+?) сум\. Яндекс: оплаты (.+?) сум, меню (.+?) сум\.$/, "Menyu istisnolaridan oldingi savdo. Menyu: $1 so'm. Banket tanlanmasidan tashqari: $3 so'm. Яндекс: to'lovlar $4 so'm, menyu $5 so'm."],
  [/^(\d+) замечани\S* к бухгалтеру$/, "Buxgalterga $1 ta izoh"],
  [/^(\d+) замечани\S*$/, "$1 ta izoh"],
  [/^(\d+) выше ([\d\s]+)$/, "$2 dan yuqori: $1"],
  [/^([\d.,]+%) выручки Retro$/, "Retro tushumining $1"],
  [/^(\d+) дн\S* недели$/, "haftaning $1 kuni"],
  [/^(.+) · маржа (\d+%) · (.+) за (\d+) дн\S*$/, "$1 · marja $2 · $4 kunda $3"],
  [/^Выдача (.+)$/, "Berish: $1"],
  [/^Данные на (\d\d:\d\d)$/, "Ma'lumotlar $1 holatiga"],
  [/^За месяц: (.+)$/, "Oy bo'yicha: $1"],
  [/^из них Демо (.+) · (.+) Retro$/, "shundan Демо $1 · Retro'ning $2"],
  [/^Кассир передал меньше расчёта · (.+)$/, "Kassir hisobdan kam topshirdi · $1"],
  [/^Отчёт бухгалтера · (.+)$/, "Buxgalter hisoboti · $1"],
  [/^Передано (.+?) при расчёте ([\d\s]+) · разница (.+)$/, "Topshirildi $1, hisob bo'yicha $2 · farq $3"],
  [/^Передано (.+?) при расчёте ([\d\s]+)$/, "Topshirildi $1, hisob bo'yicha $2"],
  [/^Передача кассы не записана · (.+)$/, "Kassa topshirilishi yozilmagan · $1"],
  [/^Расчёт кассира (.+)$/, "Kassir hisobi $1"],
  [/^До следующего уровня (\d+) XP$/, "Keyingi darajagacha $1 XP"],
  [/^из (\d\d:\d\d)$/, "/ $1"],
  [/^из (\d+) ·$/, "/ $1 ·"],
  [/^На (.+) сум — бухгалтер ещё не принял накладные\. Эти деньги уже не на руках\.$/, "$1 so'm — buxgalter hali nakladnoylarni qabul qilmagan. Bu pul endi qo'lda emas."],
  [/^Всего оплат: (.+) сум$/, "Jami to'lovlar: $1 so'm"],
  [/^зарплата: (.+) · прочие: (.+)$/, "ish haqi: $1 · boshqa: $2"],
  [/^Оплаты продаж: (.+?) \+ Зачтённые авансы: (.+?) = (.+?) сум\. Разбивка сверена с отчётом продаж\.$/, "Savdo to'lovlari: $1 + Hisobga olingan avanslar: $2 = $3 so'm. Taqsimot savdo hisoboti bilan solishtirilgan."],
  [/^Новые типы оплаты iiko показаны отдельно: (.+?)\. Выручка включает продажи, оплаченные авансом; новые авансы за будущие заказы не добавляются\. Банкет — только блюда с меткой «БЕХРУЗ»\. Блок P&L — бухгалтерские показатели всего ресторана из отчёта iiko «Прибыли и убытки»; фильтр направлений на него не влияет\. Дегустация и Счёт Шефа показаны отдельно по себестоимости операций без выручки и не прибавляются к продажам\. Способы оплаты показывают распределение продаж, а не поступления денег\. Чистая прибыль после расходов дэшборда равна чистой прибыли iiko минус расходы кассы и бухгалтерии за выбранные даты\. Все продажи выбранных направлений: (.+?) сум; вне банкетной выборки: (.+?) сум\.$/, "iiko'ning yangi to'lov turlari alohida ko'rsatilgan: $1. Tushum avans bilan to'langan savdoni o'z ichiga oladi; kelgusi buyurtmalar uchun yangi avanslar qo'shilmaydi. Banket — faqat «БЕХРУЗ» belgili taomlar. P&L bloki — iiko'ning «Foyda va zararlar» hisobotidan butun restoranning buxgalteriya ko'rsatkichlari; yo'nalishlar filtri unga ta'sir qilmaydi. Degustatsiya va Счёт Шефа tushumsiz operatsiyalar tannarxi bo'yicha alohida ko'rsatilgan va savdoga qo'shilmaydi. To'lov usullari pul tushumini emas, savdo taqsimotini ko'rsatadi. Dashbord xarajatlaridan keyingi sof foyda iiko sof foydasidan tanlangan sanalardagi kassa va buxgalteriya xarajatlarini ayirganiga teng. Tanlangan yo'nalishlarning barcha savdosi: $2 so'm; banket tanlanmasidan tashqari: $3 so'm."],
];

