  "Выручка включает продажи, оплаченные авансом; новые авансы за будущие заказы не добавляются. Банкет — только блюда с меткой «БЕХРУЗ». Блок P&L — бухгалтерские показатели всего ресторана из отчёта iiko «Прибыли и убытки»; фильтр направлений на него не влияет. Дегустация и Счёт Шефа показаны отдельно по себестоимости операций без выручки и не прибавляются к продажам. Способы оплаты показывают распределение продаж, а не поступления денег.": "Tushumga avans bilan to'langan savdolar kiradi; kelgusi buyurtmalar uchun yangi avanslar qo'shilmaydi. Banket — faqat «БЕХРУЗ» belgili taomlar. P&L bloki — iiko «Foyda va zararlar» hisobotidan butun restoranning buxgalteriya ko'rsatkichlari; yo'nalishlar filtri unga ta'sir qilmaydi. Degustatsiya va Shef hisobi tushumsiz operatsiyalar tannarxi bo'yicha alohida ko'rsatilgan va savdoga qo'shilmaydi. To'lov usullari pul tushumini emas, savdo taqsimotini ko'rsatadi.",
  "Полная смена кассы Retro, включая банкетное отделение; авансы по отделениям не разделены.": "Retro kassasining to'liq smenasi, banket bo'limi bilan birga; avanslar bo'limlar bo'yicha ajratilmagan.",
  "Предоплаты оценены как разница смены и продаж. Это не реестр авансов; для передачи денег требуется сверка фактической наличности. Тип «Наличные (Инкасса QR)» передаётся отдельно и не включён в формулу.": "Oldindan to'lovlar smena va savdo farqi sifatida baholangan. Bu avanslar reyestri emas; pulni topshirish uchun haqiqiy naqd pulni solishtirish kerak. «Наличные (Инкасса QR)» turi alohida topshiriladi va formulaga kiritilmagan.",
  "В iiko найдено новое отделение Бехруз. Проверьте распределение выручки.": "iiko'da yangi Behruz bo'limi topildi. Tushum taqsimotini tekshiring.",
  "В iiko появилось неизвестное отделение Retro. Разделение выручки требует проверки.": "iiko'da noma'lum Retro bo'limi paydo bo'ldi. Tushumni ajratishni tekshirish kerak.",
  "В iiko появилось неизвестное отделение школы. Разделение выручки требует проверки.": "iiko'da maktabning noma'lum bo'limi paydo bo'ldi. Tushumni ajratishni tekshirish kerak.",
