  "Чистая прибыль после расходов дэшборда равна чистой прибыли iiko минус расходы кассы и бухгалтерии за выбранные даты.": "Dashborddagi xarajatlardan keyingi sof foyda iiko sof foydasidan tanlangan kunlardagi kassa va buxgalteriya xarajatlarini ayirganiga teng.",
